/**
 * LRU cache with TTL. Entries expire after ttlMs; the cache holds at most
 * `capacity` entries and evicts the least-recently-used one when full.
 */
export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed, seq }
  let seq = 0 // monotonically increasing access counter; breaks lastUsed ties
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        // TTL has passed: treat the entry as a miss and drop it.
        entries.delete(key)
        return undefined
      }
      entry.lastUsed = now
      entry.seq = ++seq
      return entry.value
    },
    set(key, value) {
      const now = clock()
      const nextSeq = ++seq
      if (entries.size >= capacity && !entries.has(key)) {
        // evict the least-recently-used entry (oldest lastUsed, then oldest access)
        const victim = [...entries.entries()].sort(
          (a, b) => (a[1].lastUsed - b[1].lastUsed) || (a[1].seq - b[1].seq)
        )[0]
        entries.delete(victim[0])
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now, seq: nextSeq })
    },
    size() {
      return entries.size
    },
    _raw() {
      return [...entries.entries()]
    },
  }
}

